        py: 'def knapsack(weights, values, W):\n    dp = [0] * (W + 1)\n    for wt, val in zip(weights, values):\n        for w in range(W, wt - 1, -1):     # DESCENDING!\n            dp[w] = max(dp[w], dp[w - wt] + val)\n    return dp[W]\n\n# ascending would allow reusing the same item\n# => that is the UNBOUNDED knapsack\n\ndef knapsack_2d(weights, values, W):       # keeps choices\n    n = len(weights)\n    dp = [[0] * (W + 1) for _ in range(n + 1)]\n    for i in range(1, n + 1):\n        wt, val = weights[i-1], values[i-1]\n        for w in range(W + 1):\n            dp[i][w] = dp[i-1][w]                       # skip\n            if w >= wt:\n                dp[i][w] = max(dp[i][w],\n                               dp[i-1][w - wt] + val)   # take\n    return dp\n\n# O(nW) — pseudo-polynomial, NOT polynomial in input size',
        q: { q: 'In the 1D version you loop capacity ASCENDING. What have you built?', o: ['The same thing, slightly faster', 'Unbounded knapsack — items can be reused', 'A broken loop that crashes'], x: 1, w: 'Ascending lets dp[w−wt] already include the current item. That is exactly the unbounded variant.' }
